package com.example

import com.example.ExamQuestionHelper.QSpec

internal object BuddhismG11LiveExamSriLankaBank1 {
  private const val T = "ශ්‍රී ලංකාවේ බුදුසසුනේ ඉතිහාසය හා පුනර්ජීවනය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "ශ්‍රී ලංකාවේ බුදුසසුනේ ඉතිහාසය අදාළ කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("ශ්‍රී ලංකාවට බුදුදහම නිල වශයෙන් රැගෙන වැඩම කළ මහරහතන් වහන්සේ කවුද?", "අනුබුදු මිහිඳු මහරහතන් වහන්සේ", "සංඝමිත්තා තෙරණිය", "මජ්ඣන්තික හිමි", "මහාදේව හිමි", "දේවානම්පියතිස්ස රජ සමයේ මිහිඳු හිමියෝ මිහින්තලයට වැඩම කළහ."),
    q("මිහිඳු මහරහතන් වහන්සේ ලංකාවට වැඩම කළේ කුමන පොහෝ දිනකදීද?", "පොසොන් පුන් පොහෝ දින", "වෙසක් පුන් පොහෝ දින", "ඇසළ පුන් පොහෝ දින", "දුරුතු පුන් පොහෝ දින", "මිහිඳු හිමියන්ගේ ලංකාගමනය සිදු වූයේ පොසොන් පුන් පොහෝ දිනදීය."),
    q("මිහිඳු හිමියන් මිහින්තලේ අඹස්තලේදී දේවානම්පියතිස්ස රජුගේ බුද්ධිය පරීක්ෂා කිරීමට ඇසූ ප්‍රසිද්ධ ප්‍රශ්නය කුමක්ද?", "අඹ ගස හා සෙසු ගස් ගැනය (අඹ කඳුවන ප්‍රශ්නය)", "සිංහයා ගැනය", "ගඟ ගැනය", "හිරු ගැනය", "දඹදිව අඹ ගසක් හා වෙනත් ගස් ගැන අසමින් රජුගේ නුවණ පරීක්ෂා කළහ."),
    q("රජුගේ බුද්ධිය පරීක්ෂා කිරීමෙන් පසු මිහිඳු හිමියන් රජුට හා පිරිසට දේශනා කළ ප්‍රථම සූත්‍රය කුමක්ද?", "චූළහත්ථිපදෝපම සූත්‍රය", "රතන සූත්‍රය", "මංගල සූත්‍රය", "ධම්මචක්ක සූත්‍රය", "ඇතුගේ පා සටහනින් ඇතා හඳුනා ගන්නාක් මෙන් බුදු ගුණ පෙන්වූහ."),
    q("ලංකාවේ ප්‍රථම විහාරය ලෙස මිහිඳු හිමියන්ට රජු විසින් පූජා කරන ලද්දේ කුමන උයනද?", "මහමෙවුනා උයන (මහාවිහාරය)", "රන්මසු උයන", "නන්දන උයන", "ගෝතමී උයන", "අනුරාධපුර මහමෙවුනා උයන බුදු සසුනේ මූලස්ථානය විය."),
    q("ශ්‍රී මහා බෝධීන් වහන්සේගේ දක්ෂිණ ශාඛාව රැගෙන ලංකාවට වැඩම කළ තෙරණිය කවුද?", "සංඝමිත්තා මහරහත් තෙරණිය", "අනුලා තෙරණිය", "ඛේමා තෙරණිය", "කිසාගෝතමී තෙරණිය", "අශෝක අධිරාජයාගේ දියණිය වූ සංඝමිත්තා තෙරණිය බෝධි ශාඛාව වැඩම කළහ."),
    q("ශ්‍රී මහා බෝධි ශාඛාව ලංකාවට වැඩම කරවා ගොඩබසින ලද්දේ කුමන වරායෙන්ද?", "ජම්부කෝළ වරාය (දඹකොළ පටුන)", "මහාතිත්ත වරාය", "කොළඹ වරාය", "ගාලු වරාය", "නොගැඹුරු මුහුදේ රජු මඟට ගොස් සාදුකාර දී බෝධිය පිළිගත්තේය."),
    q("ලංකාවේ ඉදි වූ ප්‍රථම ස්තූපය (චෛත්‍යය) කුමක්ද?", "ථූපාරාමය", "රුවන්වැලි මහ සෑය", "මිරිසවැටිය", "ජේතවනාරාමය", "දේවානම්පියතිස්ස රජු මිහිඳු හිමියන්ගේ උපදෙසින් ථූපාරාමය කරවූහ."),
    q("ථූපාරාම චෛත්‍යයේ තැන්පත් කර ඇති බුදුරදුන්ගේ ශ්‍රී ධාතුව කුමක්ද?", "දකුණු අකුධාතුව", "නළා ධාතුව", "වාම ශ්‍රී දළදා වහන්සේ", "උඩුකුරු දළදා වහන්සේ", "බුදුරදුන්ගේ දකුණු අකුධාතුව ථූපාරාමයේ තැන්පත් කර ඇත."),
    q("ලක්දිව බුදුසසුන පිහිටුවීම සඳහා පැමිණි ධර්මදූත පිරිසේ සිටි සාමණේර හිමිනම කවුද?", "සුමන සාමණේරයන්", "භණ්ඩුක උපාසක", "ඉට්ඨිය හිමි", "උත්තිය හිමි", "අනගාරික සුමන සාමණේරයන් ශ්‍රී මහා බෝධි ගෙන ඒමටද දායක වූහ."),
    q("දුටුගැමුණු රජතුමා විසින් ඉදිකරන ලද මහා ස්වර්ණමය මහා චෛත්‍යය කුමක්ද?", "රුවන්වැලි මහ සෑය (ස්වර්ණමාලි මහා සෑය)", "ලෝවාමහාපාය", "අභයගිරි ස්තූපය", "මිරිසවැටිය", "මහත් භක්තියෙන් හා ධාතු නිධානෝත්සවයෙන් රුවන්වැලි සෑය ඉදි කළහ."),
    q("දුටුගැමුණු රජතුමා මහා සංඝයා වෙනුවෙන් කරවූ නව මහින් මාලිගය හැඳින්වෙන්නේ කුමන නමකින්ද?", "ලෝවාමහාපාය", "මනෝරාම ප්‍රාසාදය", "විජය ප්‍රාසාදය", "ප්‍රාසාද මන්දිරය", "ලෝහ තහතුවලින් වසුන් කළ ලෝවාමහාපාය භික්ෂූන්ගේ උපෝසතාගාරය විය."),
    q("අනුරාධපුර යුගයේ ඉදි වූ ලංකාවේ උස්ම ස්තූපය කුමක්ද?", "ජේතවනාරාමය (මහසෙන් රජු කරවන ලදී)", "අභයගිරිය", "රුවన్‌වැලි සෑය", "මිරිසවැටිය", "මහසෙන් රජු විසින් ජේතවනාරාමය කරවන ලදී."),
    q("සතරවන සියවසේදී මෙරටට ලැබී වර්තමානයේ ශ්‍රී ලංකාවේ බෞද්ධයන්ගේ මුදුන්මල්කඩ වන උතුම් පූජා වස්තුව කුමක්ද?", "වාම ශ්‍රී දළදා වහන්සේ", "ශ්‍රී පාදස්ථානය", "නළා ධාතුව", "පත්‍ර ධාතුව", "කිත්සිරිමෙවන් රජ සමයේ ගුහาสීව රජුගේ දියණිය හා බෑණා විසින් දළදා වහන්සේ එවන ලදී."),
    q("ලංකාවට දළදා වහන්සේ වැඩම කරන ලද්දේ කවුරුන් විසින්ද?", "දන්ත කුමරු හා හේමමාලා කුමරිය", "මිහිඳු හිමි හා සංඝමිත්තා", "දේවානම්පියතිස්ස රජු", "අශෝක රජු", "ඔවුහු රහසේ උත්තම දළදා වහන්සේ කේශකලාපයේ සඟවාගෙන වැඩම කළහ.")
  )
}
